package io.knowledgebrain.collaboration;
import java.util.*;import java.time.*;import java.util.concurrent.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import static org.junit.jupiter.api.Assertions.*;import org.springframework.web.server.ResponseStatusException;
import io.knowledgebrain.contracts.collaboration.rubricassessment.v1.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_COLLABORATION_DATABASE_URL",matches=".+")
class RubricGradingStoreIntegrationTest {
 AssignmentRubricStoreIntegrationTest f;SubmissionStore submissions;SubmissionGradeStore grades;RubricGradingStore store;AssignmentRubricStore.Rubric rubric;SubmissionStore.Submission answer;UUID author;
 @BeforeEach void setup(){f=new AssignmentRubricStoreIntegrationTest();f.setup();rubric=f.change(0,1,f.initial()).rubric();f.f.store.state(f.f.group,f.f.space,f.f.study,f.assignment,f.f.f.owner,1,"OPEN",f.f.f.trace);submissions=new SubmissionStore(f.f.f.source,f.f.store,Clock.systemUTC());author=f.f.f.ids.next();answer=submissions.submit(f.f.group,f.f.space,f.f.study,f.assignment,author,0,2,f.f.f.key(),"Answer <script>",f.f.f.trace).submission();grades=new SubmissionGradeStore(f.f.f.source,f.f.store,submissions,Clock.systemUTC());store=new RubricGradingStore(f.f.f.source,grades,f.store,submissions,Clock.systemUTC());}
 RubricGradingInput input(int a,int b,String reason){return new RubricGradingInput("RUBRIC",1,2,rubric.version(),reason,null,List.of(new RubricGradingInput.Item(rubric.criteria().get(0).criterionId(),a,"분석 <script>"),new RubricGradingInput.Item(rubric.criteria().get(1).criterionId(),b,"Sources")));}
 RubricGradingStore.View change(long version,RubricGradingInput input){return store.change(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),f.f.f.owner,version,input,f.f.f.trace);}
 RubricGradingStore.View get(UUID actor,boolean owner){return store.get(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),actor,owner);}
 RubricGradingStore.Assessment basis(long version,UUID actor,boolean owner){return store.forVersion(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),version,actor,owner);}
 RubricGradingInput direct(int score,String reason,long sub,long assignment){return new RubricGradingInput("DIRECT",sub,assignment,0,reason,score,List.of());}
 void status(int code,org.junit.jupiter.api.function.Executable action){assertEquals(code,assertThrows(ResponseStatusException.class,action).getStatusCode().value());}
 int assessments(){return f.f.f.jdbc.queryForObject("SELECT count(*) FROM submission_rubric_assessment WHERE submission_id=?",Integer.class,answer.submissionId());}
 @Test void absenceDoesNotAllocateAndManualGradeHasExplicitNullBasis(){assertNull(get(author,false).assessment());assertNull(get(author,false).grade());assertFalse(get(author,false).canWrite());assertEquals(0,assessments());status(404,()->basis(1,author,false));var manual=change(0,direct(75,"Manual",1,2));assertNull(manual.assessment());assertNull(basis(1,author,false));assertEquals(0,assessments());}
 @Test void fullGradeBasisAndBothOutboxesCommitWithExactSourceAndFrozenDefinition()throws Exception{var v=change(0,input(45,30,"Total75"));var a=v.assessment();assertEquals(75,v.grade().score());assertEquals(19,tools.jackson.databind.json.JsonMapper.builder().build().readTree(tools.jackson.databind.json.JsonMapper.builder().build().writeValueAsString(a)).size());assertEquals(rubric,a.rubric());assertEquals(v.grade().gradeId(),a.gradeId());assertEquals(1,a.gradeVersion());assertEquals(author,a.authorId());assertEquals("AUTHOR_AND_OWNER",a.audience());assertEquals(a,basis(1,author,false));assertEquals(v.grade(),grades.get(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),author,false).grade());assertEquals(7,a.assessmentId().version());assertEquals(1,assessments());var e=RubricAssessmentEnvelopeV1.parseFrom(f.f.f.jdbc.queryForObject("SELECT payload FROM outbox_event WHERE aggregateid=?",byte[].class,a.assessmentId()));var p=RubricAssessmentSnapshotV1.parseFrom(e.getPayload());assertEquals(75,p.getScore());assertEquals(1,p.getVersion());assertEquals(1,p.getGradeVersion());assertEquals(a.criteria().getFirst().comment(),p.getCriteria(0).getComment());assertEquals(rubric.criteria().get(0).title(),p.getRubric().getCriteria(0).getTitle());assertEquals(1,p.getRubric().getAssignmentVersion());assertEquals(2,p.getAssignmentVersion());assertEquals(f.f.f.trace,e.getTraceId());assertEquals(f.f.space.toString(),e.getSpaceId());assertEquals(f.f.f.owner.toString(),e.getActorId());assertEquals("RubricAssessmentRecorded",e.getEventType());assertEquals(2,f.f.f.jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregateid IN (?,?)",Integer.class,a.assessmentId(),a.gradeId()));}
 @Test void sameTotalDifferentDistributionCreatesNewGradeAndRetainsOriginalBasis(){var a=change(0,input(45,30,"Same total"));assertEquals(a,change(1,input(45,30,"Same total")));status(412,()->change(0,input(45,30,"Same total")));var b=change(1,input(50,25,"Same total"));assertEquals(75,b.grade().score());assertEquals(2,b.grade().version());assertNotEquals(a.assessment().assessmentId(),b.assessment().assessmentId());assertEquals(a.assessment(),basis(1,author,false));assertEquals(b.assessment(),basis(2,author,false));assertEquals(2,assessments());}
 @Test void explicitModeSwitchAtUnchangedScoreCreatesRevisionAndLegacyNoOpRemainsNoOp(){var a=change(0,input(45,30,"Keep"));var legacy=grades.change(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),f.f.f.owner,1,new SubmissionGradeInput(75,"Keep",1,2),f.f.f.trace);assertEquals(a.grade(),legacy);assertEquals(a.assessment(),get(author,false).assessment());var b=change(1,direct(75,"Keep",1,2));assertEquals(2,b.grade().version());assertNull(b.assessment());assertNull(basis(2,author,false));assertEquals(b,change(2,direct(75,"Keep",1,2)));var c=change(2,input(45,30,"Keep"));assertEquals(3,c.grade().version());assertEquals(2,assessments());assertEquals(a.assessment(),basis(1,author,false));}
 @Test void invalidOrIncompleteCriteriaAndStaleSourceCannotAllocate(){for(var cmd:List.of(input(61,30,"Over maximum"),input(45,41,"Over maximum")))status(400,()->change(0,cmd));var a=input(45,30,"Wrong");status(409,()->change(0,new RubricGradingInput("RUBRIC",1,2,99,a.reason(),null,a.criteria())));status(409,()->change(0,new RubricGradingInput("RUBRIC",1,2,1,a.reason(),null,List.of(a.criteria().getLast(),a.criteria().getFirst()))));status(409,()->change(0,new RubricGradingInput("RUBRIC",1,2,1,a.reason(),null,List.of(a.criteria().getFirst()))));status(409,()->change(0,new RubricGradingInput("RUBRIC",2,2,1,a.reason(),null,a.criteria())));status(409,()->change(0,new RubricGradingInput("RUBRIC",1,1,1,a.reason(),null,a.criteria())));assertNull(get(author,false).grade());assertEquals(0,assessments());}
 @Test void missingOptionalRubricRejectsCalculationWithoutBreakingDirectGrade(){var other=f.f.create(f.f.f.key()).assignment();f.f.store.state(f.f.group,f.f.space,f.f.study,other.assignmentId(),f.f.f.owner,1,"OPEN",f.f.f.trace);var submitted=submissions.submit(f.f.group,f.f.space,f.f.study,other.assignmentId(),author,0,2,f.f.f.key(),"Optional",f.f.f.trace).submission();status(409,()->store.change(f.f.group,f.f.space,f.f.study,other.assignmentId(),submitted.submissionId(),f.f.f.owner,0,input(45,30,"No rubric"),f.f.f.trace));var manual=store.change(f.f.group,f.f.space,f.f.study,other.assignmentId(),submitted.submissionId(),f.f.f.owner,0,direct(75,"Direct",1,2),f.f.f.trace);assertEquals(75,manual.grade().score());assertNull(manual.rubric());assertNull(manual.assessment());}
 @Test void exactZeroAndFullScoresAreRealGrades(){var zero=change(0,input(0,0,"Zero"));assertEquals(0,zero.grade().score());assertNotNull(zero.assessment());var full=change(1,input(60,40,"Full"));assertEquals(100,full.grade().score());assertEquals(0,basis(1,author,false).score());}
 @Test void resubmissionRetainsOriginalBasisAndRequiresExplicitNewSource(){var v=change(0,input(45,30,"Original"));submissions.submit(f.f.group,f.f.space,f.f.study,f.assignment,author,1,2,f.f.f.key(),"New answer",f.f.f.trace);assertEquals(v.assessment(),get(author,false).assessment());status(409,()->change(1,input(45,30,"Old source")));var old=input(45,30,"New review");var current=change(1,new RubricGradingInput("RUBRIC",2,2,1,old.reason(),null,old.criteria()));assertEquals(2,current.grade().submissionVersion());assertEquals(2,current.grade().version());assertEquals(v.assessment(),basis(1,author,false));}
 @Test void retractionRemainsPinnedAndUnchangedCalculationCannotRestoreIt(){var v=change(0,input(45,30,"Keep"));var markers=new GradeRetractionStore(f.f.f.source,f.f.store,submissions,Clock.systemUTC());markers.change(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),f.f.f.owner,1,0,new GradeRetractionInput("RETRACTED","Wrong"),f.f.f.trace);assertEquals(v,change(1,input(45,30,"Keep")));var b=change(1,input(50,25,"Keep"));assertNull(markers.get(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),author,false,2).retraction());assertEquals("RETRACTED",markers.get(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),author,false,1).retraction().state());assertEquals(v.assessment(),basis(1,author,false));}
 @Test void ownerSelfAndPeersCannotBypassOriginalGradePrivacy(){var v=change(0,input(45,30,"Private"));status(404,()->get(f.f.f.ids.next(),false));status(404,()->basis(1,f.f.f.ids.next(),false));status(403,()->store.change(f.f.group,f.f.space,f.f.study,f.assignment,answer.submissionId(),author,1,input(45,30,"Private"),f.f.f.trace));assertFalse(get(author,true).canWrite());status(404,()->store.forVersion(f.f.group,f.f.space,f.f.f.ids.next(),f.assignment,answer.submissionId(),1,author,false));assertEquals(v.assessment(),basis(1,author,false));}
 @Test void closedParentsAllowGradesButArchiveFreezesBothModesAndRetainsReads(){change(0,input(45,30,"Before"));f.f.store.state(f.f.group,f.f.space,f.f.study,f.assignment,f.f.f.owner,2,"CLOSED",f.f.f.trace);var v=change(1,input(40,30,"Closed"));f.f.parent.store.state(f.f.group,f.f.space,f.f.study,f.f.f.owner,1,"RETIRED",f.f.f.trace);assertFalse(get(f.f.f.owner,true).canWrite());status(409,()->change(2,input(40,30,"Closed")));status(409,()->change(2,direct(70,"Closed",1,2)));assertEquals(v.assessment(),basis(2,author,false));}
 @Test void localConstraintsRejectWrongGradeActorAndRubricProvenance(){var v=change(0,input(45,30,"FK"));for(String update:List.of("grade_version=999999","rubric_version=999999","grader_id=author_id","assignment_version=999999","submission_version=999999"))assertThrows(org.springframework.dao.DataAccessException.class,()->f.f.f.jdbc.update("UPDATE submission_rubric_assessment SET "+update+" WHERE assessment_id=?",v.assessment().assessmentId()));assertEquals(v.assessment(),basis(1,author,false));}
 @Test void simultaneousManualAndRubricCommandsHaveOneSharedCasWinner()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var barrier=new CyclicBarrier(2);var futures=new ArrayList<Future<Boolean>>();for(var in:List.of(input(45,30,"Rubric"),direct(80,"Manual",1,2)))futures.add(pool.submit(()->{barrier.await();try{change(0,in);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(futures.get(0).get(),futures.get(1).get());assertEquals(1,get(author,false).grade().version());assertTrue(assessments()<=1);}}
 @Test void assessmentOutboxFailureRollsBackBothGradeAndBasis(){String constraint="assessment_fail_"+answer.submissionId().toString().replace("-","");f.f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+" CHECK(aggregatetype<>'rubric-assessment' OR trace_id<>'"+f.f.f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->change(0,input(45,30,"Fail")));assertNull(get(author,false).grade());assertEquals(0,assessments());}finally{f.f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}var a=change(0,input(45,30,"Keep"));f.f.f.jdbc.execute("ALTER TABLE outbox_event ADD CONSTRAINT "+constraint+" CHECK(aggregatetype<>'rubric-assessment' OR trace_id<>'"+f.f.f.trace+"') NOT VALID");try{assertThrows(RuntimeException.class,()->change(1,input(50,25,"Fail")));assertEquals(a.grade(),get(author,false).grade());assertEquals(a.assessment(),basis(1,author,false));assertEquals(1,assessments());}finally{f.f.f.jdbc.execute("ALTER TABLE outbox_event DROP CONSTRAINT "+constraint);}}
}
